22	export function formatCurrency(v: number): string {
23	    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v);
24	}
25	
26	export function formatCompactCurrency(v: number): string {
27	    if (v >= 1e6) return `R$ ${(v / 1e6).toFixed(1)}M`;
28	    if (v >= 1e3) return `R$ ${(v / 1e3).toFixed(0)}k`;
29	    return formatCurrency(v);
30	}
