169	export function buildDashPipeline(items: IPosAquisicaoItem[]): IDashPipelineItem[] {
170	    const pa = items.filter((i) => i.statusDue === 'pos_aquisicao');
171	    return allDashEtapas
172	        .map((et) => {
173	            const inEtapa = pa.filter((i) => (i._posAquisicao || ({} as any)).etapaAtual === et.id);
174	            const dias = inEtapa.map((i) => {
175	                const p = i._posAquisicao || ({} as any);
176	                const refD = p.ultimaMovimentacao || p.dataAquisicao;
177	                return refD
178	                    ? Math.round((Date.now() - new Date(refD).getTime()) / (1000 * 60 * 60 * 24))
179	                    : 0;
180	            });
181	            const diasMedio =
182	                dias.length > 0 ? Math.round(dias.reduce((s, d) => s + d, 0) / dias.length) : 0;
183	            const litItems = inEtapa.filter((i) => (i._posAquisicao || ({} as any)).emLitigio);
184	            return {
185	                etapa: et.short,
186	                etapaId: et.id,
187	                nome: et.nome,
188	                qtd: inEtapa.length,
189	                valor: inEtapa.reduce((s, i) => s + i.valorLiquido, 0),
190	                color: et.color,
191	                diasMedio,
192	                litCount: litItems.length,
193	                litValor: litItems.reduce((s, i) => s + i.valorLiquido, 0),
194	            };
195	        })
196	        .filter((d) => d.qtd > 0);
197	}
