217	                nomeFull: i.nomeCredor,
218	                etapa: et.short,
219	                etapaId: p.etapaAtual,
220	                dias,
221	                valor: Math.round(i.valorLiquido / 1000),
222	                lit: !!p.emLitigio,
223	                color: et.color,
224	            };
225	        })
226	        .sort((a, b) => b.dias - a.dias);
227	}
