334	export function buildProcPipeline(processos: IProcesso[]): IDashPipelineItem[] {
335	    const byTipo = new Map<string, IProcesso[]>();
336	    processos.forEach((p) => {
337	        const list = byTipo.get(p.tipo) ?? [];
338	        list.push(p);
339	        byTipo.set(p.tipo, list);
340	    });
341	
342	    return tiposProcesso
343	        .map((t) => {
344	            const list = byTipo.get(t.id);
345	            if (!list || list.length === 0) return null;
346	            const valor = list.reduce((s, p) => s + p.valorCausa, 0);
347	            const diasSum = list.reduce((s, p) => s + getDiasParado(p.ultimaMovimentacao), 0);
348	            const diasMedio = Math.round(diasSum / list.length);
349	            const urgentes = list.filter((p) => p.urgente);
350	            return {
351	                etapa: t.short,
352	                etapaId: t.id,
353	                nome: t.nome,
354	                qtd: list.length,
355	                valor,
356	                color: t.color,
357	                diasMedio,
358	                litCount: urgentes.length,
359	                litValor: urgentes.reduce((s, p) => s + p.valorCausa, 0),
360	            };
361	        })
362	        .filter(Boolean) as IDashPipelineItem[];
363	}
