import type {
    IPosAquisicaoItem,
    IProcesso,
    IEtapa,
    IDocConfig,
    IDashPipelineItem,
    IDashAgingItem,
    IDashAlerta,
} from './types';
import {
    posAquisicaoEtapas,
    posAqEtapasExtra,
    posAqEtapasCompensacao,
    posAqAllDocs,
    allDashEtapas,
    tiposProcesso,
    etapasProcessuais,
    CREDITORIO_ETAPA_COLORS,
    PRECATORIO_ETAPA_COLORS,
} from './constants';

export function formatCurrency(v: number): string {
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v);
}

export function formatCompactCurrency(v: number): string {
    if (v >= 1e6) return `R$ ${(v / 1e6).toFixed(1)}M`;
    if (v >= 1e3) return `R$ ${(v / 1e3).toFixed(0)}k`;
    return formatCurrency(v);
}

export function formatBRL(n: number): string {
    if (n === 0) return 'R$ 0,00';
    return n.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
}

export function parseBRL(v: string | number | undefined): number {
    if (!v && v !== 0) return 0;
    let s = String(v)
        .replace(/[^\d,.-]/g, '')
        .trim();
    if (!s) return 0;
    const commaMatch = s.match(/,(\d{1,2})$/);
    if (commaMatch) {
        s = s.replace(/\./g, '').replace(',', '.');
    } else {
        const dotMatch = s.match(/\.(\d{1,2})$/);
        if (dotMatch && !s.includes(',')) {
            // US decimal, leave as-is
        } else {
            s = s.replace(/\./g, '');
        }
    }
    return parseFloat(s) || 0;
}

export function toBRLInput(n: number): string {
    if (n === 0) return '0,00';
    return n.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

export function buildPosAqPipeline(
    tipoCreditorio: string,
    ordemExpedicao: string,
    finalidade: string,
): IEtapa[] {
    let stages: IEtapa[];
    if (finalidade === 'compensacao') {
        stages = posAqEtapasCompensacao;
    } else if (tipoCreditorio !== 'creditorio') {
        stages = posAquisicaoEtapas;
    } else if (ordemExpedicao === 'exp_antes') {
        stages = [posAqEtapasExtra[0], posAqEtapasExtra[1], ...posAquisicaoEtapas];
    } else {
        stages = [
            posAquisicaoEtapas[0],
            posAqEtapasExtra[0],
            posAqEtapasExtra[1],
            posAquisicaoEtapas[2],
            posAquisicaoEtapas[3],
            posAquisicaoEtapas[4],
        ];
    }

    // Creditório: paleta Figma (roxo → índigo → verde).
    if (tipoCreditorio === 'creditorio' && finalidade !== 'compensacao') {
        return stages.map((etapa) => ({
            ...etapa,
            color: CREDITORIO_ETAPA_COLORS[etapa.id] ?? etapa.color,
        }));
    }

    // Precatório / Investimento: paleta Figma própria (distinta do Creditório).
    if (tipoCreditorio !== 'creditorio' && finalidade !== 'compensacao') {
        return stages.map((etapa) => ({
            ...etapa,
            color: PRECATORIO_ETAPA_COLORS[etapa.id] ?? etapa.color,
        }));
    }

    return stages;
}

export function getPosAqDocs(
    tipoCreditorio: string,
    ordemExpedicao: string,
    finalidade: string,
): IDocConfig[] {
    const pipeline = buildPosAqPipeline(tipoCreditorio, ordemExpedicao, finalidade);
    const etapaIds = new Set(pipeline.map((e) => e.id));
    return posAqAllDocs.filter((d) => etapaIds.has(d.etapa));
}

export function getDiasParado(dataRef: string | undefined): number {
    if (!dataRef) return 0;
    return Math.round((Date.now() - new Date(dataRef).getTime()) / (1000 * 60 * 60 * 24));
}

export function getDocsCount(pa: IPosAquisicaoItem['_posAquisicao']): number {
    const docs = getPosAqDocs(
        pa.tipoCreditorio || 'precatorio',
        pa.ordemExpedicao || 'reg_antes',
        pa.finalidade || 'investimento',
    );
    return docs.filter((d) => (pa.docsEnviados || {})[d.id]).length;
}

export function getTotalDocs(pa: IPosAquisicaoItem['_posAquisicao']): number {
    return getPosAqDocs(
        pa.tipoCreditorio || 'precatorio',
        pa.ordemExpedicao || 'reg_antes',
        pa.finalidade || 'investimento',
    ).length;
}

export function getEtapaById(id: string): IEtapa {
    const allEtapas = [
        ...posAquisicaoEtapas,
        ...posAqEtapasExtra,
        ...posAqEtapasCompensacao.filter((e) => !posAquisicaoEtapas.find((p) => p.id === e.id)),
    ];
    return allEtapas.find((e) => e.id === id) || posAquisicaoEtapas[0];
}

export function fmtMovDate(d: string): string {
    return new Date(d + 'T00:00:00').toLocaleDateString('pt-BR', {
        day: '2-digit',
        month: 'short',
        year: 'numeric',
    });
}

/** Data curta para mobile (dd/mm/aaaa). */
export function fmtMovDateCompact(d: string): string {
    return new Date(d + 'T00:00:00').toLocaleDateString('pt-BR');
}

export function fmtTaskDate(d: string): { text: string; color: string; label: string } {
    const dt = new Date(d + 'T00:00:00');
    const now = new Date();
    const diff = Math.round((dt.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
    const formatted = dt.toLocaleDateString('pt-BR', { day: '2-digit', month: 'short' });
    if (diff < 0)
        return { text: formatted, color: '#dc2626', label: `${Math.abs(diff)}d atrasada` };
    if (diff <= 3) return { text: formatted, color: '#d97706', label: `${diff}d restantes` };
    return { text: formatted, color: '#888', label: `${diff}d` };
}

export function buildDashPipeline(items: IPosAquisicaoItem[]): IDashPipelineItem[] {
    const pa = items.filter((i) => i.statusDue === 'pos_aquisicao');
    return allDashEtapas
        .map((et) => {
            const inEtapa = pa.filter((i) => (i._posAquisicao || ({} as any)).etapaAtual === et.id);
            const dias = inEtapa.map((i) => {
                const p = i._posAquisicao || ({} as any);
                const refD = p.ultimaMovimentacao || p.dataAquisicao;
                return refD
                    ? Math.round((Date.now() - new Date(refD).getTime()) / (1000 * 60 * 60 * 24))
                    : 0;
            });
            const diasMedio =
                dias.length > 0 ? Math.round(dias.reduce((s, d) => s + d, 0) / dias.length) : 0;
            const litItems = inEtapa.filter((i) => (i._posAquisicao || ({} as any)).emLitigio);
            return {
                etapa: et.short,
                etapaId: et.id,
                nome: et.nome,
                qtd: inEtapa.length,
                valor: inEtapa.reduce((s, i) => s + i.valorLiquido, 0),
                color: et.color,
                diasMedio,
                litCount: litItems.length,
                litValor: litItems.reduce((s, i) => s + i.valorLiquido, 0),
            };
        })
        .filter((d) => d.qtd > 0);
}

export function buildDashAging(items: IPosAquisicaoItem[]): IDashAgingItem[] {
    const pa = items.filter(
        (i) =>
            i.statusDue === 'pos_aquisicao' &&
            (i._posAquisicao || ({} as any)).etapaAtual !== 'pagamento' &&
            (i._posAquisicao || ({} as any)).etapaAtual !== 'conclusao',
    );
    return pa
        .map((i) => {
            const p = i._posAquisicao || ({} as any);
            const refDate = p.ultimaMovimentacao || p.dataAquisicao;
            const dias = refDate
                ? Math.round((Date.now() - new Date(refDate).getTime()) / (1000 * 60 * 60 * 24))
                : 0;
            const et = allDashEtapas.find((e) => e.id === p.etapaAtual) || allDashEtapas[0];
            return {
                itemId: i.id,
                nome: i.nomeCredor.length > 20 ? i.nomeCredor.slice(0, 18) + '…' : i.nomeCredor,
                nomeFull: i.nomeCredor,
                etapa: et.short,
                etapaId: p.etapaAtual,
                dias,
                valor: Math.round(i.valorLiquido / 1000),
                lit: !!p.emLitigio,
                color: et.color,
            };
        })
        .sort((a, b) => b.dias - a.dias);
}

export function buildDashAlertas(items: IPosAquisicaoItem[]): IDashAlerta[] {
    const pa = items.filter((i) => i.statusDue === 'pos_aquisicao');
    const notifs: IDashAlerta[] = [];
    const movTemplates = [
        {
            tipo: 'mov',
            desc: 'JUNTADA DE CERTIDÃO DA CONTADORIA',
            tipoMov: 'Juntada',
            diario: null,
        },
        {
            tipo: 'mov',
            desc: 'DECISÃO — Deferido pedido de registro de cessão',
            tipoMov: 'Decisão',
            diario: null,
        },
        {
            tipo: 'mov',
            desc: 'DESPACHO — Expedição de ofício requisitório',
            tipoMov: 'Despacho',
            diario: null,
        },
        {
            tipo: 'mov',
            desc: 'PETIÇÃO DE CESSÃO protocolada no PJe',
            tipoMov: 'Petição',
            diario: null,
        },
        { tipo: 'mov', desc: 'DISTRIBUÍDO POR SORTEIO', tipoMov: 'Distribuição', diario: null },
        {
            tipo: 'pub',
            desc: 'INTIMAÇÃO — Prazo de 15 dias para manifestação',
            tipoMov: null,
            diario: 'DJe',
        },
        {
            tipo: 'pub',
            desc: 'PUBLICAÇÃO — Homologação de cessão de crédito',
            tipoMov: null,
            diario: 'DJe',
        },
        {
            tipo: 'pub',
            desc: 'PUBLICAÇÃO — Despacho de expedição de ofício',
            tipoMov: null,
            diario: 'DJe',
        },
        { tipo: 'mov', desc: 'JUNTADA DE PROCURAÇÃO atualizada', tipoMov: 'Juntada', diario: null },
        {
            tipo: 'pub',
            desc: 'INTIMAÇÃO — Cite-se para confirmar cessão em 5 dias',
            tipoMov: null,
            diario: 'DJe',
        },
    ];
    const baseDate = new Date();
    const mesesCurto = [
        'jan.',
        'fev.',
        'mar.',
        'abr.',
        'mai.',
        'jun.',
        'jul.',
        'ago.',
        'set.',
        'out.',
        'nov.',
        'dez.',
    ];

    pa.forEach((item, idx) => {
        const template = movTemplates[idx % movTemplates.length];
        const dt = new Date(baseDate);
        dt.setDate(dt.getDate() - idx);
        const dataStr = dt.toISOString().slice(0, 10);
        const nome =
            item.nomeCredor.length > 22 ? item.nomeCredor.slice(0, 20) + '…' : item.nomeCredor;
        const et =
            allDashEtapas.find((e) => e.id === (item._posAquisicao || ({} as any)).etapaAtual) ||
            allDashEtapas[0];
        const categoriaLabel =
            template.tipoMov ?? (template.tipo === 'pub' ? 'Publicação' : 'Movimentação');
        const dataFmtCard = `${dt.getDate()} de ${mesesCurto[dt.getMonth()]}`;
        notifs.push({
            itemId: String(item.id),
            tipo: template.tipo,
            tipoMov: template.tipoMov,
            diario: template.diario,
            desc: template.desc,
            nome,
            nomeFull: item.nomeCredor,
            npu: item.npuOriginario,
            tribunal: item.tribunal,
            etapa: et.short,
            etapaColor: et.color,
            data: dataStr,
            dataFmt: dt.toLocaleDateString('pt-BR', { day: '2-digit', month: 'short' }),
            dataFmtCard,
            categoriaLabel,
        });
    });
    return notifs.sort((a, b) => b.data.localeCompare(a.data));
}

export function buildProcPipeline(processos: IProcesso[]): IDashPipelineItem[] {
    const byTipo = new Map<string, IProcesso[]>();
    processos.forEach((p) => {
        const list = byTipo.get(p.tipo) ?? [];
        list.push(p);
        byTipo.set(p.tipo, list);
    });

    return tiposProcesso
        .map((t) => {
            const list = byTipo.get(t.id);
            if (!list || list.length === 0) return null;
            const valor = list.reduce((s, p) => s + p.valorCausa, 0);
            const diasSum = list.reduce((s, p) => s + getDiasParado(p.ultimaMovimentacao), 0);
            const diasMedio = Math.round(diasSum / list.length);
            const urgentes = list.filter((p) => p.urgente);
            return {
                etapa: t.short,
                etapaId: t.id,
                nome: t.nome,
                qtd: list.length,
                valor,
                color: t.color,
                diasMedio,
                litCount: urgentes.length,
                litValor: urgentes.reduce((s, p) => s + p.valorCausa, 0),
            };
        })
        .filter(Boolean) as IDashPipelineItem[];
}

export function buildProcDashAging(processos: IProcesso[]): IDashAgingItem[] {
    return processos
        .map((p) => {
            const dias = getDiasParado(p.ultimaMovimentacao);
            const et = etapasProcessuais.find((e) => e.id === p.etapaAtual) || etapasProcessuais[0];
            const _autoraFull = p.parteAutora.join(', ');
            return {
                itemId: p.id,
                nome: _autoraFull.length > 20 ? _autoraFull.slice(0, 18) + '…' : _autoraFull,
                nomeFull: _autoraFull,
                etapa: et.short,
                etapaId: p.etapaAtual,
                dias,
                valor: Math.round(p.valorCausa / 1000),
                lit: p.urgente,
                color: et.color,
            };
        })
        .sort((a, b) => b.dias - a.dias);
}

export function buildProcDashAlertas(processos: IProcesso[]): IDashAlerta[] {
    const movTemplates = [
        { tipo: 'mov', desc: 'JUNTADA DE PETIÇÃO DE AGRAVO', tipoMov: 'Juntada', diario: null },
        {
            tipo: 'mov',
            desc: 'DECISÃO — Deferido pedido de liminar',
            tipoMov: 'Decisão',
            diario: null,
        },
        { tipo: 'mov', desc: 'DESPACHO — Expedição de ofício', tipoMov: 'Despacho', diario: null },
        { tipo: 'mov', desc: 'PETIÇÃO PROTOCOLADA NO PJE', tipoMov: 'Petição', diario: null },
        { tipo: 'mov', desc: 'DISTRIBUÍDO POR SORTEIO', tipoMov: 'Distribuição', diario: null },
        {
            tipo: 'pub',
            desc: 'INTIMAÇÃO — Prazo de 15 dias para manifestação',
            tipoMov: null,
            diario: 'DJe',
        },
        { tipo: 'pub', desc: 'PUBLICAÇÃO — Homologação de recurso', tipoMov: null, diario: 'DJe' },
        {
            tipo: 'pub',
            desc: 'PUBLICAÇÃO — Despacho de expedição de certidão',
            tipoMov: null,
            diario: 'DJe',
        },
        { tipo: 'mov', desc: 'JUNTADA DE PROCURAÇÃO atualizada', tipoMov: 'Juntada', diario: null },
        { tipo: 'pub', desc: 'INTIMAÇÃO — Manifestação em 5 dias', tipoMov: null, diario: 'DJe' },
    ];
    const baseDate = new Date();
    const mesesCurto = [
        'jan.',
        'fev.',
        'mar.',
        'abr.',
        'mai.',
        'jun.',
        'jul.',
        'ago.',
        'set.',
        'out.',
        'nov.',
        'dez.',
    ];

    const notifs: IDashAlerta[] = [];

    processos.forEach((proc, idx) => {
        const template = movTemplates[idx % movTemplates.length];
        const dt = new Date(baseDate);
        dt.setDate(dt.getDate() - idx);
        const dataStr = dt.toISOString().slice(0, 10);
        const _autoraAlertas = proc.parteAutora.join(', ');
        const nome =
            _autoraAlertas.length > 22 ? _autoraAlertas.slice(0, 20) + '…' : _autoraAlertas;
        const et = etapasProcessuais.find((e) => e.id === proc.etapaAtual) || etapasProcessuais[0];
        const categoriaLabel =
            template.tipoMov ?? (template.tipo === 'pub' ? 'Publicação' : 'Movimentação');
        const dataFmtCard = `${dt.getDate()} de ${mesesCurto[dt.getMonth()]}`;
        notifs.push({
            itemId: String(proc.id),
            tipo: template.tipo,
            tipoMov: template.tipoMov,
            diario: template.diario,
            desc: template.desc,
            nome,
            nomeFull: _autoraAlertas,
            npu: proc.npu,
            tribunal: proc.tribunal,
            etapa: et.short,
            etapaColor: et.color,
            data: dataStr,
            dataFmt: dt.toLocaleDateString('pt-BR', { day: '2-digit', month: 'short' }),
            dataFmtCard,
            categoriaLabel,
        });
    });

    return notifs.sort((a, b) => b.data.localeCompare(a.data));
}

export function buildDashEsferaLoa(items: IPosAquisicaoItem[]) {
    const pa = items.filter((i) => i.statusDue === 'pos_aquisicao');
    const esferaMap: Record<string, string> = {
        Federal: 'FEDERAL',
        Estadual: 'ESTADUAL',
        Municipal: 'MUNICIPAL',
    };
    const esferaColors: Record<string, string> = {
        FEDERAL: '#2563eb',
        ESTADUAL: '#0891b2',
        MUNICIPAL: '#7c3aed',
    };

    const result: Record<
        string,
        {
            color: string;
            qtd: number;
            valor: number;
            loas: Record<string, { qtd: number; valor: number }>;
            subs: Record<string, { qtd: number; valor: number }>;
        }
    > = {};

    pa.forEach((i) => {
        const esf = esferaMap[i.esfera] || 'FEDERAL';
        if (!result[esf])
            result[esf] = { color: esferaColors[esf], qtd: 0, valor: 0, loas: {}, subs: {} };
        result[esf].qtd++;
        result[esf].valor += i.valorLiquido;
        const loa = String(i.loa);
        if (!result[esf].loas[loa]) result[esf].loas[loa] = { qtd: 0, valor: 0 };
        result[esf].loas[loa].qtd++;
        result[esf].loas[loa].valor += i.valorLiquido;
        if (esf === 'FEDERAL') {
            const key = i.enteDevedor;
            if (!result[esf].subs[key]) result[esf].subs[key] = { qtd: 0, valor: 0 };
            result[esf].subs[key].qtd++;
            result[esf].subs[key].valor += i.valorLiquido;
        } else {
            const stateMatch = i.enteDevedor.match(/(?:de\s+|do\s+)(.+)$/);
            const key = stateMatch ? stateMatch[1] : i.esfera;
            if (!result[esf].subs[key]) result[esf].subs[key] = { qtd: 0, valor: 0 };
            result[esf].subs[key].qtd++;
            result[esf].subs[key].valor += i.valorLiquido;
        }
    });
    const totalValor = pa.reduce((s, i) => s + i.valorLiquido, 0);
    const allSubs: {
        nome: string;
        qtd: number;
        valor: number;
        esf: string;
        color: string;
    }[] = [];
    Object.entries(result).forEach(([esf, d]) => {
        Object.entries(d.subs).forEach(([nome, s]) =>
            allSubs.push({ nome, ...s, esf, color: d.color }),
        );
    });
    allSubs.sort((a, b) => b.valor - a.valor);
    return { data: result, total: pa.length, totalValor, allSubs };
}

export const tipoMovColors: Record<string, string> = {
    Juntada: '#2563eb',
    Distribuição: '#7c3aed',
    Documento: '#d97706',
    Decisão: '#16a34a',
    Petição: '#0891b2',
    Despacho: '#ea580c',
};

export const taskPrioColors: Record<string, string> = {
    alta: '#dc2626',
    media: '#d97706',
    baixa: '#16a34a',
};

export const taskPrioLabels: Record<string, string> = {
    alta: 'Alta',
    media: 'Média',
    baixa: 'Baixa',
};

export const etapaShortToId: Record<string, string> = {
    REG: 'registro',
    BLQ: 'bloqueio',
    PAG: 'pagamento',
    TRANS: 'transferencia',
    FIM: 'conclusao',
    EXP: 'expedicao',
    SUB: 'subida',
    CJF: 'cjf',
    CVLD: 'cvld',
    PGFN: 'peticao_pgfn',
};

export function parsePct(v: string): number {
    return parseFloat(String(v).replace(',', '.').replace('%', '')) || 0;
}

export function formatDateMask(raw: string): string {
    let v = raw.replace(/\D/g, '');
    if (v.length > 2) v = v.slice(0, 2) + '/' + v.slice(2);
    if (v.length > 5) v = v.slice(0, 5) + '/' + v.slice(5);
    if (v.length > 10) v = v.slice(0, 10);
    return v;
}

